import{az as e,P as a,Q as r,aQ as i}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const u=JSON.parse('{"title":"React 实现 Keep-Alive 方案总结","description":"","frontmatter":{},"headers":[],"relativePath":"框架/react/react/keep-alive.md","filePath":"框架/react/react/keep-alive.md","lastUpdated":1785246304000}'),o={name:"框架/react/react/keep-alive.md"};function l(n,t,s,d,c,g){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="react-实现-keep-alive-方案总结" tabindex="-1">React 实现 Keep-Alive 方案总结 <a class="header-anchor" href="#react-实现-keep-alive-方案总结" aria-label="Permalink to “React 实现 Keep-Alive 方案总结”">​</a></h1><p>React <strong>没有</strong>像 Vue <code>&lt;keep-alive&gt;</code> 那样的官方组件，但社区和官方有多条实现路径，核心思路均为 <strong>&quot;隐藏不销毁&quot;</strong>。</p><hr><h2 id="一、生产推荐-react-activation" tabindex="-1">一、生产推荐：react-activation <a class="header-anchor" href="#一、生产推荐-react-activation" aria-label="Permalink to “一、生产推荐：react-activation”">​</a></h2><p>社区最成熟的 Keep-Alive 库，将组件提升到主渲染树之外保留，需要时再插回。</p><ul><li><strong>安装</strong>：<code>pnpm add react-activation</code></li><li><strong>用法</strong>：用 <code>&lt;AliveScope&gt;</code> 包裹根节点，用 <code>&lt;KeepAlive&gt;</code> 包裹需要缓存的组件</li><li><strong>特点</strong>： <ul><li>提供 <code>useAliveController</code> 生命周期钩子（类似 Vue 的 <code>activated</code> / <code>deactivated</code>）</li><li>支持组件级缓存，可按需缓存指定组件</li><li>稳定，生产可用，社区活跃</li></ul></li><li><strong>缺点</strong>： <ul><li>存在一些已知小坑（可参考其 GitHub Issues）</li><li>增加了包体积和一定复杂度</li></ul></li><li><strong>仓库</strong>：<a href="https://github.com/CJY0208/react-activation" target="_blank" rel="noreferrer">CJY0208/react-activation</a></li></ul><hr><h2 id="二、css-隐藏法-diy-最简" tabindex="-1">二、CSS 隐藏法（DIY 最简） <a class="header-anchor" href="#二、css-隐藏法-diy-最简" aria-label="Permalink to “二、CSS 隐藏法（DIY 最简）”">​</a></h2><p>所有页面常驻渲染，通过 <code>display: none</code> 切换显隐。</p><ul><li><strong>优点</strong>：实现极其简单，状态天然保留</li><li><strong>缺点</strong>：常驻渲染有性能开销，不卸载导致副作用持续执行</li><li><strong>适用场景</strong>：页面少、轻量的项目</li></ul><hr><h2 id="三、suspense-离屏-diy-进阶" tabindex="-1">三、Suspense 离屏（DIY 进阶） <a class="header-anchor" href="#三、suspense-离屏-diy-进阶" aria-label="Permalink to “三、Suspense 离屏（DIY 进阶）”">​</a></h2><p>利用 React 的 <code>Suspense</code> + 抛出 Promise 来暂停子树 reconciliation。</p><ul><li><strong>原理</strong>：被隐藏的组件不再参与 React 的协调过程，比 CSS 隐藏法更省性能</li><li><strong>优点</strong>：性能优于 CSS 隐藏，接近官方 Offscreen 的思路</li><li><strong>缺点</strong>：需自行实现缓存调度逻辑（路由切换时的缓存/恢复/清理策略）</li><li><strong>适用场景</strong>：有定制需求、愿维护源码的团队</li><li><strong>参考</strong>：<a href="https://juejin.cn/post/7312304122535149604" target="_blank" rel="noreferrer">掘金实战文章</a></li></ul><hr><h2 id="四、activity-原-offscreen-—-官方实验-api" tabindex="-1">四、Activity（原 Offscreen）— 官方实验 API <a class="header-anchor" href="#四、activity-原-offscreen-—-官方实验-api" aria-label="Permalink to “四、Activity（原 Offscreen）— 官方实验 API”">​</a></h2><p>React 官方正在实验的离屏渲染 API，<code>&lt;Offscreen mode=&quot;hidden&quot;&gt;</code> 可以隐藏但不卸载组件树。</p><ul><li><strong>状态</strong>：仍在实验阶段，尚未稳定，暂不建议生产使用</li><li><strong>前景</strong>：这是最接近 Vue <code>&lt;keep-alive&gt;</code> 的官方解法，未来稳定后将是最佳选择</li><li><strong>相关</strong>：飞冰（ICE）框架已有基于实验版的 keep-alive 封装</li><li><strong>参考</strong>：<a href="https://github.com/facebook/react/pull/27640" target="_blank" rel="noreferrer">facebook/react PR #27640</a></li></ul><hr><h2 id="方案对比" tabindex="-1">方案对比 <a class="header-anchor" href="#方案对比" aria-label="Permalink to “方案对比”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>成熟度</th><th>性能</th><th>实现难度</th><th>推荐场景</th></tr></thead><tbody><tr><td><strong>react-activation</strong></td><td>高</td><td>好</td><td>低</td><td>生产项目首选</td></tr><tr><td><strong>CSS 隐藏法</strong></td><td>—</td><td>一般</td><td>最低</td><td>页面少的轻量项目</td></tr><tr><td><strong>Suspense 离屏</strong></td><td>中</td><td>较好</td><td>中</td><td>有定制需求的团队</td></tr><tr><td><strong>Activity（Offscreen）</strong></td><td>实验中</td><td>最佳</td><td>—</td><td>未来官方方案，暂不推荐</td></tr></tbody></table><hr><h2 id="快速决策" tabindex="-1">快速决策 <a class="header-anchor" href="#快速决策" aria-label="Permalink to “快速决策”">​</a></h2><ul><li><strong>现在就要用在生产项目</strong> → 选 <code>react-activation</code></li><li><strong>可以等</strong> → 关注 React 官方 Activity API 的稳定进展</li><li><strong>页面很少且简单</strong> → CSS 隐藏法足够</li><li><strong>想深入理解原理并有定制需求</strong> → Suspense 离屏方案</li></ul>',24)])])}const f=e(o,[["render",l]]);export{u as __pageData,f as default};
